33	
34	static bool IsEmptyInput(gert::TilingContext *context)
35	{
36	    (void)context;
37	    return false;
38	}
39	
40	ASCENDC_EXTERN_C ge::graphStatus TilingQuantFlashAttn(gert::TilingContext *context)
41	{
42	    OP_LOGW(context, "QuantFlashAttn TilingQuantFlashAttn start.");
43	
44	    auto platformInfoPtr = context->GetPlatformInfo();
45	    OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return ge::GRAPH_FAILED);
46	
47	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
48	    if (ascendcPlatform.GetCurNpuArch() == NpuArch::DAV_3510) {
49	        if (IsEmptyInput(context)) {
50	            return ge::GRAPH_SUCCESS;
51	        }
52	    }
53	
54	    QfaTilingInfo qfaInfo;
55	    QfaInfoParser qfaInfoParser(context);
56	    if (qfaInfoParser.Parse(qfaInfo) != ge::GRAPH_SUCCESS) {
57	        return ge::GRAPH_FAILED;
58	    }
59	
60	    QfaChecker qfaChecker;
61	    qfaChecker.Init(qfaInfo);
62	    if (qfaChecker.Process(qfaInfo) != ge::GRAPH_SUCCESS) {
