69	ASCENDC_EXTERN_C ge::graphStatus TilingPrepareForQuantFlashAttn(gert::TilingParseContext *context)
70	{
71	    auto platformInfoPtr = context->GetPlatformInfo();
72	    OP_CHECK_IF(platformInfoPtr == nullptr, OP_LOGE(context, "platformInfoPtr is null"), return ge::GRAPH_FAILED);
73	    auto compileInfoPtr = context->GetCompiledInfo<QuantFlashAttnCompileInfo>();
74	    OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(context, "compileInfoPtr is null"), return ge::GRAPH_FAILED);
75	
76	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
77	    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
78	    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
79	    compileInfoPtr->socVersion = ascendcPlatform.GetSocVersion();
