11	/*!
12	 * \file qfa_tiling_shape.cpp
13	 * \brief QuantFlashAttn Tiling Shape implementation
14	 */
15	
16	#include <vector>
17	#include <map>
18	#include <algorithm>
19	#include "qfa_tiling_shape.h"
20	
21	namespace optiling {
22	namespace quant_flash_attn {
23	
24	static const std::map<QfaLayout, std::vector<QfaAxis>> QFA_LAYOUT_AXIS_MAP = {
25	    {QfaLayout::BSND, {QfaAxis::B, QfaAxis::S, QfaAxis::N, QfaAxis::D}},
26	    {QfaLayout::BNSD, {QfaAxis::B, QfaAxis::N, QfaAxis::S, QfaAxis::D}},
27	    {QfaLayout::TND, {QfaAxis::T, QfaAxis::N, QfaAxis::D}},
28	    {QfaLayout::NTD, {QfaAxis::N, QfaAxis::T, QfaAxis::D}},
29	    {QfaLayout::PA_BBND, {QfaAxis::Bn, QfaAxis::Bs, QfaAxis::N, QfaAxis::D}},
30	    {QfaLayout::PA_BNBD, {QfaAxis::Bn, QfaAxis::N, QfaAxis::Bs, QfaAxis::D}},
31	    {QfaLayout::PA_NZ, {QfaAxis::Bn, QfaAxis::N, QfaAxis::D1, QfaAxis::Bs, QfaAxis::D0}},
32	    {QfaLayout::LSE_BNS, {QfaAxis::B, QfaAxis::N, QfaAxis::S1}},
33	    {QfaLayout::LSE_NT, {QfaAxis::N, QfaAxis::T}}};
34	
35	namespace {
36	
37	struct CompareFuncs {
38	    static bool Equal(const int64_t &a, const int64_t &b) { return a == b; }
39	    static bool Greater(const int64_t &a, const int64_t &b) { return a > b; }
40	    static bool GreaterEqual(const int64_t &a, const int64_t &b) { return a >= b; }
41	    static bool Less(const int64_t &a, const int64_t &b) { return a < b; }
42	    static bool LessEqual(const int64_t &a, const int64_t &b) { return a <= b; }
43	    static bool NotEqual(const int64_t &a, const int64_t &b) { return a != b; }
44	    static bool IgnoreInput(const int64_t &a, const int64_t &b)
45	    {
46	        (void)a;
47	        (void)b;
48	        return true;
49	    }
50	};
51	
52	} // namespace
53	
54	const std::map<QfaCompareType, QfaCompareFunc<int64_t>> QfaTilingShapeCompare::compareFuncMap_ = {
55	    {QfaCompareType::EQUAL, CompareFuncs::Equal},
56	    {QfaCompareType::GREATER, CompareFuncs::Greater},
57	    {QfaCompareType::GREATER_EQUAL, CompareFuncs::GreaterEqual},
58	    {QfaCompareType::LESS, CompareFuncs::Less},
59	    {QfaCompareType::LESS_EQUAL, CompareFuncs::LessEqual},
60	    {QfaCompareType::NOT_EQUAL, CompareFuncs::NotEqual},
61	    {QfaCompareType::IGNORE_INPUT, CompareFuncs::IgnoreInput}};
62	
63	static ge::graphStatus GetLayoutAxes(std::vector<QfaAxis> &layoutAxes, const QfaLayout &layout,
64	                                     const std::string &opName, const std::string &funcName)
65	{
66	    auto it = QFA_LAYOUT_AXIS_MAP.find(layout);
67	    if (it == QFA_LAYOUT_AXIS_MAP.end()) {
68	        OP_LOGE(opName, "[%s] Layout %s is unsupported.", funcName.c_str(), QfaLayoutToSerialString(layout).c_str());
69	        return ge::GRAPH_FAILED;
70	    }
71	    layoutAxes = it->second;
72	    return ge::GRAPH_SUCCESS;
73	}
74	
75	bool QfaTilingShape::HasAxis(const QfaAxis &axis) const
76	{
77	    auto layoutIt = QFA_LAYOUT_AXIS_MAP.find(layout_);
78	    if (layoutIt == QFA_LAYOUT_AXIS_MAP.end()) {
79	        return false;
80	    }
81	    const auto &axes = layoutIt->second;
82	    return std::find(axes.begin(), axes.end(), axis) != axes.end();
83	}
84	
85	size_t QfaTilingShape::GetAxisIdx(const QfaAxis &axis) const
86	{
87	    if (!HasAxis(axis)) {
88	        return 0;
89	    }
90	    const auto &axes = QFA_LAYOUT_AXIS_MAP.find(layout_)->second;
91	    auto axisIt = std::find(axes.begin(), axes.end(), axis);
92	    return std::distance(axes.begin(), axisIt);
93	}
94	
95	int64_t QfaTilingShape::GetAxisNum(const QfaAxis &axis) const
96	{
97	    return HasAxis(axis) ? shape_.GetDim(GetAxisIdx(axis)) : invalidDimValue_;
98	}
99	
100	ge::graphStatus QfaTilingShape::CheckHasAxis(const QfaAxis &axis, const std::string &funcName) const
101	{
102	    if (shape_.GetDimNum() == 0) {
103	        OP_LOGE(opName_, "[%s] The dim number of %s is 0.", funcName.c_str(), name_.c_str());
104	        return ge::GRAPH_FAILED;
105	    }
106	
107	    std::vector<QfaAxis> layoutAxes;
108	    if (GetLayoutAxes(layoutAxes, layout_, opName_, funcName) != ge::GRAPH_SUCCESS) {
109	        return ge::GRAPH_FAILED;
110	    }
111	
112	    if (shape_.GetDimNum() != layoutAxes.size()) {
113	        OP_LOGE(opName_, "[%s] %s shape dimension is %zu, expected is %zu (layout %s).", funcName.c_str(),
114	                name_.c_str(), shape_.GetDimNum(), layoutAxes.size(), QfaLayoutToSerialString(layout_).c_str());
115	        return ge::GRAPH_FAILED;
116	    }
117	
118	    if (axis == QfaAxis::D) {
119	        if (HasShapeD()) {
120	            return ge::GRAPH_SUCCESS;
121	        }
122	        OP_LOGE(opName_, "[%s] %s's layout is %s, axis D or (D1, D0) does not exist.", funcName.c_str(), name_.c_str(),
123	                QfaLayoutToSerialString(layout_).c_str());
124	        return ge::GRAPH_FAILED;
125	    } else if (HasAxis(axis)) {
126	        return ge::GRAPH_SUCCESS;
127	    }
128	
129	    OP_LOGE(opName_, "[%s] %s's layout is %s, %s is not exists.", funcName.c_str(), name_.c_str(),
130	            QfaLayoutToSerialString(layout_).c_str(), QfaAxisToSerialString(axis).c_str());
131	    return ge::GRAPH_FAILED;
132	}
133	
134	std::string QfaTilingShapeCompare::CompareTypeToSerialString(const QfaCompareType compareType) const
135	{
136	    static const std::map<QfaCompareType, std::string> typeStrMap = {{QfaCompareType::EQUAL, "EQUAL"},
137	                                                                     {QfaCompareType::GREATER, "GREATER"},
138	                                                                     {QfaCompareType::GREATER_EQUAL, "GREATER_EQUAL"},
139	                                                                     {QfaCompareType::LESS, "LESS"},
140	                                                                     {QfaCompareType::LESS_EQUAL, "LESS_EQUAL"},
141	                                                                     {QfaCompareType::NOT_EQUAL, "NOT_EQUAL"}};
142	    auto it = typeStrMap.find(compareType);
143	    return (it != typeStrMap.end()) ? it->second : "UNKNOWN";
144	}
145	
146	std::string QfaTilingShapeCompare::CompareTypeToSerialSymbolString(const QfaCompareType &compareType) const
147	{
148	    static const std::map<QfaCompareType, std::string> symbolMap = {
149	        {QfaCompareType::EQUAL, "=="}, {QfaCompareType::GREATER, ">"},     {QfaCompareType::GREATER_EQUAL, ">="},
150	        {QfaCompareType::LESS, "<"},   {QfaCompareType::LESS_EQUAL, "<="}, {QfaCompareType::NOT_EQUAL, "!="}};
151	    auto it = symbolMap.find(compareType);
152	    return (it != symbolMap.end()) ? it->second : "UNKNOWN";
153	}
154	
155	ge::graphStatus QfaTilingShapeCompare::GetExpectedShape(gert::Shape &shapeExpected,
156	                                                        const QfaTilingShapeCompareParam &param,
157	                                                        const std::string &funcName) const
158	{
159	    switch (layout_) {
160	        case QfaLayout::BSND:
161	            shapeExpected = gert::Shape({param.B, param.S, param.N, param.D});
162	            break;
163	        case QfaLayout::BNSD:
164	            shapeExpected = gert::Shape({param.B, param.N, param.S, param.D});
165	            break;
166	        case QfaLayout::TND:
167	            shapeExpected = gert::Shape({param.T, param.N, param.D});
168	            break;
169	        case QfaLayout::NTD:
170	            shapeExpected = gert::Shape({param.N, param.T, param.D});
171	            break;
172	        case QfaLayout::PA_BBND:
173	            shapeExpected = gert::Shape({param.Bn, param.Bs, param.N, param.D});
174	            break;
175	        case QfaLayout::PA_BNBD:
176	            shapeExpected = gert::Shape({param.Bn, param.N, param.Bs, param.D});
177	            break;
178	        case QfaLayout::PA_NZ:
179	            shapeExpected = gert::Shape({param.Bn, param.N, param.D / param.D0, param.Bs, param.D0});
180	            break;
181	        case QfaLayout::LSE_BNS:
182	            shapeExpected = gert::Shape({param.B, param.N, param.S1});
183	            break;
184	        case QfaLayout::LSE_NT:
185	            shapeExpected = gert::Shape({param.N, param.T});
186	            break;
187	        default:
188	            OP_LOGE(opName_, "[%s] Layout %s is unsupported.", funcName.c_str(),
189	                    QfaLayoutToSerialString(layout_).c_str());
190	            return ge::GRAPH_FAILED;
191	    }
192	    return ge::GRAPH_SUCCESS;
193	}
194	
195	QfaCompareType QfaTilingShapeCompare::GetCompareType(const std::map<QfaAxis, QfaCompareType> &compareTypeMap,
196	                                                     const QfaAxis &axis) const
197	{
198	    auto it = compareTypeMap.find(axis);
199	    return (it != compareTypeMap.end()) ? it->second : QfaCompareType::EQUAL;
200	}
201	
202	ge::graphStatus QfaTilingShapeCompare::GetCompareFunc(const QfaCompareType &compareType,
203	                                                      QfaCompareFunc<int64_t> &compareFunc,
204	                                                      const std::string &funcName) const
205	{
206	    auto it = compareFuncMap_.find(compareType);
207	    if (it == compareFuncMap_.end()) {
208	        OP_LOGE(opName_, "[%s] Compare type %s is unsupported.", funcName.c_str(),
209	                CompareTypeToSerialString(compareType).c_str());
210	        return ge::GRAPH_FAILED;
211	    }
212	    compareFunc = it->second;
213	    return ge::GRAPH_SUCCESS;
214	}
215	
216	ge::graphStatus QfaTilingShapeCompare::CompareShape(QfaTilingShapeCompareParam &param,
217	                                                    const std::string &funcName) const
218	{
219	    gert::Shape shapeExpected;
220	    if (GetExpectedShape(shapeExpected, param, funcName) != ge::GRAPH_SUCCESS) {
221	        return ge::GRAPH_FAILED;
222	    }
223	
224	    std::vector<QfaAxis> layoutAxes;
225	    if (GetLayoutAxes(layoutAxes, layout_, opName_, funcName) != ge::GRAPH_SUCCESS) {
226	        return ge::GRAPH_FAILED;
227	    }
228	
229	    if (shape_.GetDimNum() != shapeExpected.GetDimNum() || shape_.GetDimNum() != layoutAxes.size()) {
230	        OP_LOGE(opName_, "[%s] %s shape dimension is %zu, expected is %zu (layout %s).", funcName.c_str(),
231	                name_.c_str(), shape_.GetDimNum(), shapeExpected.GetDimNum(), QfaLayoutToSerialString(layout_).c_str());
232	        return ge::GRAPH_FAILED;
233	    }
234	
235	    for (size_t i = 0; i < shape_.GetDimNum(); i++) {
236	        QfaAxis axis = layoutAxes[i];
237	        QfaCompareType compareType = GetCompareType(param.compareTypeMap, axis);
238	        QfaCompareFunc<int64_t> compareFunc;
239	        if (GetCompareFunc(compareType, compareFunc, funcName) != ge::GRAPH_SUCCESS) {
240	            return ge::GRAPH_FAILED;
241	        }
242	
243	        if (!compareFunc(shape_.GetDim(i), shapeExpected.GetDim(i))) {
244	            if (param.compareTypeMap.empty()) {
245	                OP_LOGE(opName_, "[%s] %s layout is %s, shape %s should be equal to %s.", funcName.c_str(),
246	                        name_.c_str(), QfaLayoutToSerialString(layout_).c_str(), GetQfaShapeStr(shape_).c_str(),
247	                        GetQfaShapeStr(shapeExpected).c_str());
248	            } else {
249	                OP_LOGE(opName_,
250	                        "[%s] %s layout is %s, shape is %s, expected is %s, "
251	                        "axis %s(%ld) should %s expected %ld.",
252	                        funcName.c_str(), name_.c_str(), QfaLayoutToSerialString(layout_).c_str(),
253	                        GetQfaShapeStr(shape_).c_str(), GetQfaShapeStr(shapeExpected).c_str(),
254	                        QfaAxisToSerialString(axis).c_str(), shape_.GetDim(i),
255	                        CompareTypeToSerialSymbolString(compareType).c_str(), shapeExpected.GetDim(i));
256	            }
257	            return ge::GRAPH_FAILED;
258	        }
259	    }
260	
261	    return ge::GRAPH_SUCCESS;
262	}
263	
264	} // namespace quant_flash_attn
265	} // namespace optiling
