323	// MultiPara — descale shape consistency (文档"一致性校验"列: descale_shape匹配关系表)
324	// ============================================================================
325	
326	ge::graphStatus QuantChecker::CheckShapeEqual(const gert::StorageShape &actual, const std::vector<int64_t> &expected,
327	                                              const std::string &paraName, const char *opName) const
328	{
329	    if (actual.GetStorageShape().GetDimNum() != expected.size()) {
330	        OP_LOGE_FOR_INVALID_SHAPEDIM(opName, paraName.c_str(),
331	                                     (std::to_string(actual.GetStorageShape().GetDimNum()) + "D").c_str(),
332	                                     (std::to_string(expected.size()) + "D").c_str());
333	        return ge::GRAPH_FAILED;
334	    }
335	    for (size_t i = 0; i < expected.size(); i++) {
336	        int64_t actDim = actual.GetStorageShape().GetDim(i);
337	        // expected[i] < 0 表示该维度不做数值校验(通配), 用于依赖 device 数据的维度
338	        if (expected[i] >= 0 && actDim != expected[i]) {
339	            OP_LOGE(opName, "%s shape dim[%zu] is %ld, expected %ld.", paraName.c_str(), i, actDim, expected[i]);
340	            return ge::GRAPH_FAILED;
341	        }
342	    }
343	    return ge::GRAPH_SUCCESS;
344	}
345	
346	ge::graphStatus QuantChecker::CheckQDescaleShapeMxFp8(const QfaTilingInfo &qfaInfo) const
347	{
348	    if (qfaInfo.quantMode != QfaQuantMode::A8C8_QKV_MXFP8_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32) {
349	        return ge::GRAPH_SUCCESS;
350	    }
351	    // 文档(descale_shape匹配关系表): MxFP8, layout_q=TND
352	    //   4D: (Q_T, Q_N, D/64, 2)              prefill场景，layout_q_descale=TND
353	    //   5D: (KV_N, Q_T, G, D/64, 2)          decode场景，layout_q_descale=N2TGD
354	    //   其中 G = Q_N / KV_N
355	    const gert::StorageShape *shape = qfaInfo.opParamInfo.qDescale.shape;
356	    int64_t D = qfaInfo.qkHeadDim;
357	    int64_t dPerGroup = (D + 63) / 64; // MxFP8 block size = 64
358	    uint32_t dimNum = shape->GetStorageShape().GetDimNum();
359	
360	    std::vector<int64_t> expected;
361	    if (dimNum == DIM_NUM_4) {
362	        expected = {qfaInfo.qTSize, qfaInfo.n1Size, dPerGroup, 2};
363	    } else if (dimNum == DIM_NUM_5) {
364	        expected = {qfaInfo.n2Size, qfaInfo.qTSize, qfaInfo.gSize, dPerGroup, 2};
365	    } else {
366	        OP_LOGE(qfaInfo.opName, "q_descale shape dim %u is unsupported, expected 4D or 5D.", dimNum);
367	        return ge::GRAPH_FAILED;
368	    }
369	
370	    // 约束: MxFP8场景下 q_descale 两种 shape 对应不同使用场景
371	    //   4D 为 prefill 场景，layout_q_descale 必须为 TND；5D 为 decode 场景，layout_q_descale 必须为 N2TGD
372	    std::string shapeStr = Ops::Base::ToString(shape->GetStorageShape());
373	    bool isDecode = (qfaInfo.layoutQDescale == QfaLayout::N2TGD);
374	    if (dimNum == DIM_NUM_4) {
375	        OP_CHECK_IF(isDecode,
376	                    OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(qfaInfo.opName, Q_DESCALE_NAME.c_str(),
377	                                                          QfaLayoutToSerialString(qfaInfo.layoutQDescale).c_str(),
378	                                                          ("q_descale shape " + shapeStr +
379	                                                           " is for prefill scene, layout_q_descale must be TND, "
380	                                                           "but got " +
381	                                                           QfaLayoutToSerialString(qfaInfo.layoutQDescale))
382	                                                              .c_str()),
383	                    return ge::GRAPH_FAILED);
384	    } else { // DIM_NUM_5, decode scene
385	        OP_CHECK_IF(!isDecode,
386	                    OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(qfaInfo.opName, Q_DESCALE_NAME.c_str(),
387	                                                          QfaLayoutToSerialString(qfaInfo.layoutQDescale).c_str(),
388	                                                          ("q_descale shape " + shapeStr +
389	                                                           " is for decode scene, layout_q_descale must be N2TGD, "
390	                                                           "but got " +
391	                                                           QfaLayoutToSerialString(qfaInfo.layoutQDescale))
392	                                                              .c_str()),
393	                    return ge::GRAPH_FAILED);
394	    }
395	    return CheckShapeEqual(*shape, expected, Q_DESCALE_NAME, qfaInfo.opName);
396	}
397	
398	ge::graphStatus QuantChecker::CheckQDescaleShapeGqaFp8(const QfaTilingInfo &qfaInfo) const
399	{
400	    if (qfaInfo.quantMode !=
401	        QfaQuantMode::A8C8_QK_FP8_E4M3_PER_TOKEN_HEAD_V_FP8_E4M3_PER_HEAD_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32) {
402	        return ge::GRAPH_SUCCESS;
403	    }
404	    // GQA_FP8_FULLQUANT, layout_q_descale=NT: 2D (N1, T)
405	    const gert::StorageShape *shape = qfaInfo.opParamInfo.qDescale.shape;
406	    std::vector<int64_t> expected = {qfaInfo.n1Size, qfaInfo.qTSize};
407	    return CheckShapeEqual(*shape, expected, Q_DESCALE_NAME, qfaInfo.opName);
408	}
