430	    }
431	    // 文档(k_descale/v_descale shape匹配关系表): MxFP8
432	    //   TND:      (KV_T, KV_N, D/64, 2)              - 4D
433	    //   PA_BNBD:  (Bn, KV_N, Bs, D/64, 2)            - 5D
434	    //   PA_NZ:    (Bn, KV_N, Bs/16, D/64, 16, 2)     - 6D
435	    const gert::StorageShape *shape = qfaInfo.opParamInfo.kDescale.shape;
436	    int64_t D = qfaInfo.qkHeadDim;
437	    int64_t dPerGroup = (D + 63) / 64;
438	    uint32_t dimNum = shape->GetStorageShape().GetDimNum();
439	
440	    std::vector<int64_t> expected;
441	    if (qfaInfo.kvLayout == QfaLayout::TND) {
442	        expected = {qfaInfo.kTSize, qfaInfo.n2Size, dPerGroup, 2};
443	    } else if (qfaInfo.kvLayout == QfaLayout::PA_BNBD) {
444	        expected = {qfaInfo.totalBlockNum, qfaInfo.n2Size, qfaInfo.blockSize, dPerGroup, 2};
445	    } else if (qfaInfo.kvLayout == QfaLayout::PA_NZ) {
446	        expected = {qfaInfo.totalBlockNum, qfaInfo.n2Size, qfaInfo.blockSize / 16, dPerGroup, 16, 2};
447	    } else {
448	        OP_LOGE(qfaInfo.opName, "k_descale shape check: kv_layout %s is unsupported.",
449	                QfaLayoutToSerialString(qfaInfo.kvLayout).c_str());
450	        return ge::GRAPH_FAILED;
451	    }
452	
453	    if (expected.size() != dimNum) {
454	        OP_LOGE(qfaInfo.opName, "k_descale shape dim %u does not match layout %s, expected %zuD.", dimNum,
455	                QfaLayoutToSerialString(qfaInfo.kvLayout).c_str(), expected.size());
456	        return ge::GRAPH_FAILED;
457	    }
458	    return CheckShapeEqual(*shape, expected, K_DESCALE_NAME, qfaInfo.opName);
459	}
