461	ge::graphStatus QuantChecker::CheckKDescaleShapeGqaFp8(const QfaTilingInfo &qfaInfo) const
462	{
463	    if (qfaInfo.quantMode !=
464	        QfaQuantMode::A8C8_QK_FP8_E4M3_PER_TOKEN_HEAD_V_FP8_E4M3_PER_HEAD_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32) {
465	        return ge::GRAPH_SUCCESS;
466	    }
467	    // GQA_FP8_FULLQUANT (PA_BNBD 强制): 3D (Bn, N2, Bs)
468	    const gert::StorageShape *shape = qfaInfo.opParamInfo.kDescale.shape;
469	    OP_CHECK_IF(qfaInfo.kvLayout != QfaLayout::PA_BNBD,
470	                OP_LOGE(qfaInfo.opName, "GQA_FP8_FULLQUANT only supports PA_BNBD, but got %s.",
471	                        QfaLayoutToSerialString(qfaInfo.kvLayout).c_str()),
472	                return ge::GRAPH_FAILED);
473	    std::vector<int64_t> expected = {qfaInfo.totalBlockNum, qfaInfo.n2Size, qfaInfo.blockSize};
474	    return CheckShapeEqual(*shape, expected, K_DESCALE_NAME, qfaInfo.opName);
475	}
