492	
493	ge::graphStatus QuantChecker::CheckVDescaleShapeMxFp8(const QfaTilingInfo &qfaInfo) const
494	{
495	    if (qfaInfo.quantMode != QfaQuantMode::A8C8_QKV_MXFP8_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32) {
496	        return ge::GRAPH_SUCCESS;
497	    }
498	    // 文档(k_descale/v_descale shape匹配关系表): MxFP8
499	    //   TND:      (KV_T/64, KV_N, D, 2)              - 4D
500	    //   PA_BNBD:  (Bn, KV_N, Bs/64, D, 2)            - 5D
501	    //   PA_NZ:    (Bn, KV_N, D/16, Bs/64, 16, 2)     - 6D
502	    const gert::StorageShape *shape = qfaInfo.opParamInfo.vDescale.shape;
503	    int64_t D = qfaInfo.vHeadDim; // v_descale 的 D 用 vHeadDim
504	    uint32_t dimNum = shape->GetStorageShape().GetDimNum();
505	
506	    std::vector<int64_t> expected;
507	    if (qfaInfo.kvLayout == QfaLayout::TND) {
508	        // TND(非PA)场景: dim0 = Σ ceil(curLen, 64), 依赖 cu_seqlens_kv 的实际数值。
509	        // tiling 阶段 cu_seqlens_kv 为 device tensor, host 侧无法安全读取,
510	        // 因此 dim0 不做数值校验(用 -1 占位), 仅校验维度数为 4D 及 dim[1..3]。
511	        expected = {-1, qfaInfo.n2Size, D, 2};
512	    } else if (qfaInfo.kvLayout == QfaLayout::PA_BNBD) {
513	        expected = {qfaInfo.totalBlockNum, qfaInfo.n2Size, qfaInfo.blockSize / 64, D, 2};
514	    } else if (qfaInfo.kvLayout == QfaLayout::PA_NZ) {
515	        expected = {qfaInfo.totalBlockNum, qfaInfo.n2Size, D / 16, qfaInfo.blockSize / 64, 16, 2};
516	    } else {
517	        OP_LOGE(qfaInfo.opName, "v_descale shape check: kv_layout %s is unsupported.",
518	                QfaLayoutToSerialString(qfaInfo.kvLayout).c_str());
519	        return ge::GRAPH_FAILED;
520	    }
521	
522	    if (expected.size() != dimNum) {
523	        OP_LOGE(qfaInfo.opName, "v_descale shape dim %u does not match layout %s, expected %zuD.", dimNum,
524	                QfaLayoutToSerialString(qfaInfo.kvLayout).c_str(), expected.size());
525	        return ge::GRAPH_FAILED;
526	    }
527	    return CheckShapeEqual(*shape, expected, V_DESCALE_NAME, qfaInfo.opName);
528	}
