558	int64_t QuantChecker::CalcVDescaleTndDim0(const QfaTilingInfo &qfaInfo) const
559	{
560	    // TND 场景下 v_descale dim0 的精确计算依赖 cu_seqlens_kv 的 device 数据,
561	    // tiling(host)阶段无法安全读取, 该函数已不再被 CheckVDescaleShape 调用,
562	    // 保留仅供其他场景或后续 host 数据可用时使用。
563	    return (qfaInfo.kTSize + 64 - 1) / 64;
