585	
586	ge::graphStatus QuantChecker::CheckDescaleDtype(const QfaTilingInfo &qfaInfo) const
587	{
588	    // 文档约束(一致性校验):
589	    //   MxFP8 场景下, q/k/v descale 的 tensor_type 仅支持 FLOAT8_E8M0
590	    //   GQA_FP8_FULLQUANT 场景下, q/k/v descale 的 tensor_type 仅支持 FLOAT32
591	    if (qfaInfo.quantMode != QfaQuantMode::A8C8_QKV_MXFP8_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32 &&
592	        qfaInfo.quantMode !=
593	            QfaQuantMode::A8C8_QK_FP8_E4M3_PER_TOKEN_HEAD_V_FP8_E4M3_PER_HEAD_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32) {
594	        return ge::GRAPH_SUCCESS;
595	    }
596	
597	    const auto it = DESCALE_DTYPE_TABLE.find(qfaInfo.quantMode);
598	    const ge::DataType expectedDtype = it->second.first;
599	    const std::string expectedDtypeStr = it->second.second;
600	
601	    const auto CheckDescaleDtype = [&qfaInfo, this, expectedDtype, &expectedDtypeStr](const QfaRequiredParaInfo &slot,
602	                                                                                      const std::string &paraName) -> ge::graphStatus {
603	        const gert::CompileTimeTensorDesc *desc = slot.desc;
604	        if (desc == nullptr) {
605	            return ge::GRAPH_SUCCESS; // 存在性校验负责
606	        }
607	        OP_CHECK_IF(desc->GetDataType() != expectedDtype,
608	                    OP_LOGE_FOR_INVALID_DTYPE(qfaInfo.opName, paraName.c_str(),
609	                                              DataTypeToSerialString(desc->GetDataType()).c_str(),
610	                                              expectedDtypeStr.c_str()),
611	                    return ge::GRAPH_FAILED);
612	        return ge::GRAPH_SUCCESS;
613	    };
614	
615	    if (CheckDescaleDtype(qfaInfo.opParamInfo.qDescale, Q_DESCALE_NAME) != ge::GRAPH_SUCCESS) {
616	        return ge::GRAPH_FAILED;
617	    }
618	    if (CheckDescaleDtype(qfaInfo.opParamInfo.kDescale, K_DESCALE_NAME) != ge::GRAPH_SUCCESS) {
619	        return ge::GRAPH_FAILED;
620	    }
621	    if (CheckDescaleDtype(qfaInfo.opParamInfo.vDescale, V_DESCALE_NAME) != ge::GRAPH_SUCCESS) {
622	        return ge::GRAPH_FAILED;
623	    }
624	    return ge::GRAPH_SUCCESS;
625	}
