627	// ============================================================================
628	// Feature — 非连续 Tensor 支持校验 (文档"特性交叉校验"列)
629	// 规则: 仅 PA 场景(layout_kv ∈ {PA_BNBD, PA_NZ})时，k/v/k_descale/v_descale
630	//       仅支持 0 轴和 1 轴非连续，其余轴必须连续；非 PA 场景均不支持非连续。
631	// ============================================================================
632	
633	ge::graphStatus QuantChecker::CheckNonContiguousSupport(const QfaTilingInfo &qfaInfo) const
634	{
635	    bool isPaLayout = (qfaInfo.kvLayout == QfaLayout::PA_BNBD || qfaInfo.kvLayout == QfaLayout::PA_NZ);
636	    if (!isPaLayout) {
637	        // 非 PA 场景: k/v/k_descale/v_descale 均不支持非连续
638	        int32_t dimIndex = 0;
639	        OP_CHECK_IF((CheckTensorContiguous(qfaInfo.opParamInfo.key.shape->GetStorageShape().GetDimNum(),
640	                                           qfaInfo.opParamInfo.key.shape->GetStorageShape(), qfaInfo.keyStrides,
641	                                           dimIndex) != ge::GRAPH_SUCCESS),
642	                    OP_LOGE(qfaInfo.opName,
643	                            "In non-PA scenarios, key must be contiguous, but dim %d is non-contiguous.", dimIndex),
644	                    return ge::GRAPH_FAILED);
645	        OP_CHECK_IF((CheckTensorContiguous(qfaInfo.opParamInfo.value.shape->GetStorageShape().GetDimNum(),
646	                                           qfaInfo.opParamInfo.value.shape->GetStorageShape(), qfaInfo.valueStrides,
647	                                           dimIndex) != ge::GRAPH_SUCCESS),
648	                    OP_LOGE(qfaInfo.opName,
649	                            "In non-PA scenarios, value must be contiguous, but dim %d is non-contiguous.", dimIndex),
650	                    return ge::GRAPH_FAILED);
651	        OP_CHECK_IF(
652	            (CheckTensorContiguous(qfaInfo.opParamInfo.kDescale.shape->GetStorageShape().GetDimNum(),
653	                                   qfaInfo.opParamInfo.kDescale.shape->GetStorageShape(), qfaInfo.kDescaleStrides,
654	                                   dimIndex) != ge::GRAPH_SUCCESS),
655	            OP_LOGE(qfaInfo.opName, "In non-PA scenarios, k_descale must be contiguous, but dim %d is non-contiguous.",
656	                    dimIndex),
657	            return ge::GRAPH_FAILED);
658	        OP_CHECK_IF(
659	            (CheckTensorContiguous(qfaInfo.opParamInfo.vDescale.shape->GetStorageShape().GetDimNum(),
660	                                   qfaInfo.opParamInfo.vDescale.shape->GetStorageShape(), qfaInfo.vDescaleStrides,
661	                                   dimIndex) != ge::GRAPH_SUCCESS),
662	            OP_LOGE(qfaInfo.opName, "In non-PA scenarios, v_descale must be contiguous, but dim %d is non-contiguous.",
663	                    dimIndex),
664	            return ge::GRAPH_FAILED);
665	        return ge::GRAPH_SUCCESS;
666	    }
667	
668	    // PA 场景(layout_kv ∈ {PA_BNBD, PA_NZ}): k/v/k_descale/v_descale 仅支持 0/1 轴非连续
669	    int32_t dimIndex = 0;
670	    OP_CHECK_IF(
671	        ((ge::GRAPH_SUCCESS != CheckTensorContiguous(qfaInfo.opParamInfo.key.shape->GetStorageShape().GetDimNum(),
672	                                                     qfaInfo.opParamInfo.key.shape->GetStorageShape(),
673	                                                     qfaInfo.keyStrides, dimIndex)) &&
674	         (dimIndex != 0 && dimIndex != 1)),
675	        OP_LOGE(qfaInfo.opName,
676	                "In PA BnNBsD/NZ scenarios, key only supports non-contiguous tensors in dimensions 0 or 1, "
677	                "but the first non-contiguous dimension is index %d.",
678	                dimIndex),
679	        return ge::GRAPH_FAILED);
680	    OP_CHECK_IF(
681	        ((ge::GRAPH_SUCCESS != CheckTensorContiguous(qfaInfo.opParamInfo.value.shape->GetStorageShape().GetDimNum(),
682	                                                     qfaInfo.opParamInfo.value.shape->GetStorageShape(),
683	                                                     qfaInfo.valueStrides, dimIndex)) &&
684	         (dimIndex != 0 && dimIndex != 1)),
685	        OP_LOGE(qfaInfo.opName,
686	                "In PA BnNBsD/NZ scenarios, value only supports non-contiguous tensors in dimensions 0 or 1, "
687	                "but the first non-contiguous dimension is index %d.",
688	                dimIndex),
689	        return ge::GRAPH_FAILED);
690	    OP_CHECK_IF(
691	        ((ge::GRAPH_SUCCESS != CheckTensorContiguous(qfaInfo.opParamInfo.kDescale.shape->GetStorageShape().GetDimNum(),
692	                                                     qfaInfo.opParamInfo.kDescale.shape->GetStorageShape(),
693	                                                     qfaInfo.kDescaleStrides, dimIndex)) &&
694	         (dimIndex != 0 && dimIndex != 1)),
695	        OP_LOGE(qfaInfo.opName,
696	                "In PA BnNBsD/NZ scenarios, k_descale only supports non-contiguous tensors in dimensions 0 or "
697	                "1, but the first non-contiguous dimension is index %d.",
698	                dimIndex),
699	        return ge::GRAPH_FAILED);
700	    OP_CHECK_IF(
701	        ((ge::GRAPH_SUCCESS != CheckTensorContiguous(qfaInfo.opParamInfo.vDescale.shape->GetStorageShape().GetDimNum(),
702	                                                     qfaInfo.opParamInfo.vDescale.shape->GetStorageShape(),
703	                                                     qfaInfo.vDescaleStrides, dimIndex)) &&
704	         (dimIndex != 0 && dimIndex != 1)),
705	        OP_LOGE(qfaInfo.opName,
706	                "In PA BnNBsD/NZ scenarios, v_descale only supports non-contiguous tensors in dimensions 0 or "
707	                "1, but the first non-contiguous dimension is index %d.",
708	                dimIndex),
709	        return ge::GRAPH_FAILED);
710	    return ge::GRAPH_SUCCESS;
711	}
