714	// Feature — Layout 匹配关系校验 (文档: layout匹配关系表)
715	// MxFP8: layout_q=TND, layout_kv∈{TND,PA_BNBD,PA_NZ}, layout_out=TND
716	// ============================================================================
717	
718	namespace {
719	struct QfaLayoutConstraintConfig {
720	    std::vector<QfaLayout> supportedKvLayouts;
721	    std::vector<QfaLayout> supportedOutLayouts;
722	    std::vector<QfaLayout> supportedQDescaleLayouts;
723	};
724	
725	const std::map<QfaQuantMode, QfaLayoutConstraintConfig> QFA_LAYOUT_CONSTRAINT_TABLE = {
726	    {QfaQuantMode::A8C8_QKV_MXFP8_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32,
727	     {{QfaLayout::TND, QfaLayout::PA_BNBD, QfaLayout::PA_NZ}, {QfaLayout::TND}, {QfaLayout::TND, QfaLayout::N2TGD}}},
728	    {QfaQuantMode::A8C8_QK_FP8_E4M3_PER_TOKEN_HEAD_V_FP8_E4M3_PER_HEAD_P_FP8_E4M3_PER_TENSOR_SOFTMAX_FP32,
729	     {{QfaLayout::PA_BNBD}, {QfaLayout::TND}, {QfaLayout::NT}}},
730	};
731	} // namespace
732	
733	ge::graphStatus QuantChecker::CheckLayoutConstraint(const QfaTilingInfo &qfaInfo) const
734	{
735	    auto it = QFA_LAYOUT_CONSTRAINT_TABLE.find(qfaInfo.quantMode);
736	    OP_CHECK_IF(it == QFA_LAYOUT_CONSTRAINT_TABLE.end(),
737	                OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(qfaInfo.opName, "quant_mode",
738	                                                      std::to_string(static_cast<uint32_t>(qfaInfo.quantMode)).c_str(),
739	                                                      "quant_mode is not supported in layout constraint table"),
740	                return ge::GRAPH_FAILED);
741	
742	    const auto &config = it->second;
743	    const std::string qLayoutStr = QfaLayoutToSerialString(qfaInfo.qLayout);
744	    const std::string quantModeStr = QfaQuantModeToSerialString(qfaInfo.quantMode);
745	
746	    OP_CHECK_IF(std::find(config.supportedKvLayouts.begin(), config.supportedKvLayouts.end(), qfaInfo.kvLayout) ==
747	                    config.supportedKvLayouts.end(),
748	                OP_LOGE(qfaInfo.opName,
749	                        "When quant_mode is MxFP8 and layout_q is %s, "
750	                        "layout_kv must be in {TND, PA_BNBD, PA_NZ}, but got %s",
751	                        qLayoutStr.c_str(), QfaLayoutToSerialString(qfaInfo.kvLayout).c_str()),
752	                return ge::GRAPH_FAILED);
753	
754	    OP_CHECK_IF(
755	        std::find(config.supportedOutLayouts.begin(), config.supportedOutLayouts.end(), qfaInfo.outLayout) ==
756	            config.supportedOutLayouts.end(),
757	        OP_LOGE(qfaInfo.opName, "When quant_mode is MxFP8 and layout_q is %s, layout_out must be TND, but got %s",
758	                qLayoutStr.c_str(), QfaLayoutToSerialString(qfaInfo.outLayout).c_str()),
759	        return ge::GRAPH_FAILED);
760	
761	    OP_CHECK_IF(
762	        std::find(config.supportedQDescaleLayouts.begin(), config.supportedQDescaleLayouts.end(),
763	                  qfaInfo.layoutQDescale) == config.supportedQDescaleLayouts.end(),
764	        OP_LOGE(qfaInfo.opName,
765	                "When quant_mode is MxFP8 and layout_q is %s, layout_q_descale must be in {TND, N2TGD}, but got %s",
766	                qLayoutStr.c_str(), QfaLayoutToSerialString(qfaInfo.layoutQDescale).c_str()),
767	        return ge::GRAPH_FAILED);
768	
769	    return ge::GRAPH_SUCCESS;
770	}
