797	
798	ge::graphStatus QuantChecker::CheckKVShape(const QfaTilingInfo &qfaInfo) const
799	{
800	    // k/v: TND -> (KV_T, KV_N, D)；PA_BNBD -> (Bn, KV_N, Bs, D)；
801	    //      PA_NZ -> (Bn, KV_N, D/32, Bs, 32)
802	    QfaTilingShapeCompareParam shapeParams;
803	    shapeParams.N = qfaInfo.n2Size;
804	    shapeParams.D = qfaInfo.qkHeadDim;
805	
806	    if (qfaInfo.kvLayout == QfaLayout::TND) {
807	        shapeParams.T = qfaInfo.kTSize;
808	    } else if (qfaInfo.kvLayout == QfaLayout::PA_BNBD || qfaInfo.kvLayout == QfaLayout::PA_NZ) {
809	        shapeParams.Bn = qfaInfo.totalBlockNum;
810	        shapeParams.Bs = qfaInfo.blockSize;
811	    }
812	    // PA_NZ k/v: D0=32, shape 为 (Bn, KV_N, D/32, Bs, 32)
813	    if (qfaInfo.kvLayout == QfaLayout::PA_NZ) {
814	        shapeParams.D0 = 32;
815	    }
816	
817	    if (keyShapeCmp_->CompareShape(shapeParams, __func__) != ge::GRAPH_SUCCESS) {
818	        return ge::GRAPH_FAILED;
819	    }
820	
821	    // v 的 D 用 qkHeadDim
822	    shapeParams.D = qfaInfo.qkHeadDim;
823	    if (valueShapeCmp_->CompareShape(shapeParams, __func__) != ge::GRAPH_SUCCESS) {
824	        return ge::GRAPH_FAILED;
825	    }
826	    return ge::GRAPH_SUCCESS;
827	}
828	
829	ge::graphStatus QuantChecker::CheckAttnOutShape(const QfaTilingInfo &qfaInfo) const
830	{
831	    // attn_out: TND -> (Q_T, Q_N, D)，D 取 vHeadDim（反量化后输出 dtype 为 BF16）
832	    QfaTilingShapeCompareParam shapeParams;
833	    shapeParams.T = qfaInfo.qTSize;
834	    shapeParams.N = qfaInfo.n1Size;
835	    shapeParams.D = qfaInfo.vHeadDim;
836	    return attnOutShapeCmp_->CompareShape(shapeParams, __func__);
837	}
838	
839	ge::graphStatus QuantChecker::CheckShapeMatch(const QfaTilingInfo &qfaInfo)
840	{
841	    SetQfaShapeCompare(qfaInfo);
842	    if (CheckQueryShape(qfaInfo) != ge::GRAPH_SUCCESS || CheckKVShape(qfaInfo) != ge::GRAPH_SUCCESS ||
843	        CheckAttnOutShape(qfaInfo) != ge::GRAPH_SUCCESS) {
844	        return ge::GRAPH_FAILED;
845	    }
846	    return ge::GRAPH_SUCCESS;
847	}
848	
849	ge::graphStatus QuantChecker::CheckFeature(const QfaTilingInfo &qfaInfo)
850	{
851	    // 文档"特性交叉校验"列(rowspan=5)包含三项:
852	    //   1. 非连续 Tensor 支持
853	    //   2. Layout 校验(layout 匹配关系表, 含 layout_q_descale)
854	    //   3. q/k/v/attn_out shape 校验(shape 匹配关系表)
855	    if (CheckNonContiguousSupport(qfaInfo) != ge::GRAPH_SUCCESS) {
856	        return ge::GRAPH_FAILED;
857	    }
858	    if (CheckLayoutConstraint(qfaInfo) != ge::GRAPH_SUCCESS) {
859	        return ge::GRAPH_FAILED;
860	    }
861	    if (CheckShapeMatch(qfaInfo) != ge::GRAPH_SUCCESS) {
862	        return ge::GRAPH_FAILED;
863	    }
864	    if (CheckInputAxisFullquant(qfaInfo) != ge::GRAPH_SUCCESS) {
865	        return ge::GRAPH_FAILED;
866	    }
867	    return ge::GRAPH_SUCCESS;
868	}
869	
870	ge::graphStatus QuantChecker::CheckN1SizeFullquant(const QfaTilingInfo &qfaInfo) const
871	{
872	    OP_CHECK_IF((qfaInfo.n1Size > N1_LIMIT || qfaInfo.n1Size < 1),
873	                OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(
874	                    qfaInfo.opName, "num_heads", std::to_string(qfaInfo.n1Size).c_str(),
875	                    "num_heads must be within the range [1, 256]"),
876	                return ge::GRAPH_FAILED);
877	    return ge::GRAPH_SUCCESS;
878	}
879	
880	ge::graphStatus QuantChecker::CheckN2SizeFullquant(const QfaTilingInfo &qfaInfo) const
881	{
882	    OP_CHECK_IF((qfaInfo.n2Size > N2_LIMIT || qfaInfo.n2Size < 1),
883	                OP_LOGE_FOR_INVALID_VALUE_WITH_REASON(
884	                    qfaInfo.opName, "num_key_value_heads", std::to_string(qfaInfo.n2Size).c_str(),
885	                    "num_key_value_heads must be within the range [1, 256]"),
886	                return ge::GRAPH_FAILED);
887	    return ge::GRAPH_SUCCESS;
888	}
889	
890	ge::graphStatus QuantChecker::CheckGSizeFullquant(const QfaTilingInfo &qfaInfo) const
891	{
892	    if (qfaInfo.gSize < 1 || qfaInfo.gSize > G_LIMIT) {
893	        std::string qShape = ToString(qfaInfo.opParamInfo.query.shape->GetStorageShape());
894	        std::string kShape = ToString(qfaInfo.opParamInfo.key.shape->GetStorageShape());
895	        std::string shapesStr = qShape + " and " + kShape;
896	        OP_LOGE_FOR_INVALID_SHAPES_WITH_REASON(
897	            qfaInfo.opName, "query and key", shapesStr.c_str(),
898	            "the axis G must be within the range [1, 64]");
899	        return ge::GRAPH_FAILED;
900	    }
901	    return ge::GRAPH_SUCCESS;
902	}
903	
904	ge::graphStatus QuantChecker::CheckInputAxisFullquant(const QfaTilingInfo &qfaInfo) const
905	{
906	    if (CheckN1SizeFullquant(qfaInfo) != ge::GRAPH_SUCCESS ||
907	        CheckN2SizeFullquant(qfaInfo) != ge::GRAPH_SUCCESS ||
908	        CheckGSizeFullquant(qfaInfo) != ge::GRAPH_SUCCESS) {
909	        return ge::GRAPH_FAILED;
910	    }
911	    return ge::GRAPH_SUCCESS;
912	}
913	
914	} // namespace quant_flash_attn
915	} // namespace optiling
